export interface Input {
  /**
   * Required stable key for this intended enrichment job. Reuse it only to retry the same job after a lost response.
   */
  idempotencyKey: string;
  /**
   * Exactly one source: mapped inline rows or an imported leadListId.
   */
  source:
    | {
        /**
         * Use rows when the supplied leads are already mapped scalar records.
         */
        kind: "rows";
        /**
         * One to 250 already-mapped scalar-valued lead records.
         *
         * @minItems 1
         * @maxItems 250
         */
        rows: [
          {
            [k: string]: string | number | boolean | null;
          },
          ...{
            [k: string]: string | number | boolean | null;
          }[]
        ];
      }
    | {
        /**
         * Use lead_list for a normalized import returned by lead_list_import.
         */
        kind: "lead_list";
        /**
         * Opaque owner-scoped leadListId returned by lead_list_import and retained for seven days.
         */
        leadListId: string;
      };
  /**
   * Exact source-header mapping. name is required; every mapped header must exist.
   */
  columnMap: {
    /**
     * Exact source header containing the business or person name.
     */
    name: string;
    /**
     * Exact source header containing a combined city, region, or service-area value.
     */
    location?: string;
    /**
     * Exact source header containing the city or locality.
     */
    city?: string;
    /**
     * Exact source header containing the state, province, or region.
     */
    region?: string;
    /**
     * Exact source header containing the company, brokerage, office, or team used to corroborate identity.
     */
    organization?: string;
    /**
     * Exact source header containing a public HTTP(S) website URL.
     */
    websiteUrl?: string;
    /**
     * Exact source header containing a named person or team public profile URL.
     */
    profileUrl?: string;
    /**
     * Exact source header containing an existing phone number used as identity evidence.
     */
    phone?: string;
    /**
     * Exact source header whose values are business or person. Omit to use defaultEntityType.
     */
    entityType?: string;
  };
  /**
   * Entity type for rows without an entityType-mapped value.
   */
  defaultEntityType?: "business" | "person";
  /**
   * When true, rows without supplied URLs may spend one exact-name Maps search. False restricts work to provided URLs.
   */
  resolveMissingUrls?: boolean;
  /**
   * Two-letter Google country code used only for missing-URL Maps resolution.
   */
  gl?: string;
  /**
   * Two-letter Google language code used only for missing-URL Maps resolution.
   */
  hl?: string;
  /**
   * Maximum public page extraction attempts per row, including its starting page.
   */
  maxPagesPerLead?: number;
  /**
   * Optional recovery after bounded page extraction finds no email. serp_snippets spends at most one current-rate SERP search per unresolved row and accepts only exact-domain email occurrences from result titles/snippets. These public occurrences do not verify deliverability or consent.
   */
  emailSearchFallback?: "off" | "serp_snippets";
  /**
   * Optional associated-person recovery for business rows. owners finds explicit owners/founders; leadership also accepts role-bearing executives, managers, and team members. It searches AI Overview plus organic results, never opens LinkedIn pages, and returns provenance-bearing public candidates rather than verified employment.
   */
  peopleDiscovery?: "off" | "owners" | "leadership";
  /**
   * Ordered query templates the calling model should author when peopleDiscovery is enabled: use one role intent per template and the placeholders {business}, {city}, {region}, or {location}, for example {business} owner of company; one focused server fallback is used when omitted.
   *
   * @minItems 1
   * @maxItems 3
   */
  peopleQueryTemplates?: [string] | [string, string] | [string, string, string];
  /**
   * Maximum associated people retained and LinkedIn-searched per business row when peopleDiscovery is enabled; maximum added SERP cost is peopleQueryTemplates length (or one fallback) plus one profile search per retained person.
   */
  maxPeoplePerLead?: number;
  /**
   * Maximum rows enriched concurrently. Default 3; maximum 5.
   */
  concurrency?: number;
  /**
   * Unique requested result formats. Defaults to both CSV and XLSX; this changes rendering only.
   *
   * @minItems 1
   * @maxItems 2
   */
  outputFormats?: ["csv" | "xlsx"] | ["csv" | "xlsx", "csv" | "xlsx"];
}

